local _PH_PARTS = {_PH_PART_1, _PH_PART_2, _PH_PART_3}
local _PHOTO_RECTS_ULTRA = {}
for _pi = 1, #_PH_PARTS do
    local _pp = _PH_PARTS[_pi]
    for _pj = 1, #_pp do _PHOTO_RECTS_ULTRA[#_PHOTO_RECTS_ULTRA + 1] = _pp[_pj] end
end

local parentCanvas = nil
local bgPanel = nil
local allWidgets = {}
local toggleRows = {}
local floatItem = nil
local isMenuOpen = false
local menuBuilt = false
local childrenBuilt = false

local function GetCanvas()
    if parentCanvas and Game:IsValid(parentCanvas) then return parentCanvas end
    parentCanvas = nil
    pcall(function()
        local InGameUITools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        local MainUI = InGameUITools.GetMainControlBaseUI()
        if not MainUI or not Game:IsValid(MainUI) then return end
        if MainUI.CanvasPanel_0 and Game:IsValid(MainUI.CanvasPanel_0) then parentCanvas = MainUI.CanvasPanel_0
        elseif MainUI.CanvasPanel_42 and Game:IsValid(MainUI.CanvasPanel_42) then parentCanvas = MainUI.CanvasPanel_42 end
    end)
    return parentCanvas
end

local function MakeBtn(parent, x, y, w, h, z, onClick)
    local btn = nil
    pcall(function()
        btn = CGame:NewObjectFromPath("/Script/UMG.Button", parent)
        if btn and slua.isValid(btn) then
            pcall(function() btn:SetColorAndOpacity(C.transparent) end)
            pcall(function() btn:SetBackgroundColor(C.transparent) end)
            pcall(function() btn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end)
            local slot = parent:AddChildToCanvas(btn)
            if slot then
                slot:SetAutoSize(false)
                slot:SetPosition(FVector2D(x, y))
                slot:SetSize(FVector2D(w, h))
                slot:SetZOrder(z or 900)
            end
            if onClick then
                pcall(function() if btn.OnClicked then btn.OnClicked:Add(function() pcall(onClick) end) end end)
                pcall(function() if btn.OnPressed then btn.OnPressed:Add(function() pcall(onClick) end) end end)
                pcall(function() if btn.OnReleased then btn.OnReleased:Add(function() pcall(onClick) end) end end)
            end
        end
    end)
    table.insert(allWidgets, btn)
    return btn
end

local function Layer(parent, x, y, w, h, color, z)
    local b = nil
    pcall(function()
        b = CGame:NewObjectFromPath("/Script/UMG.Border", parent)
        if b and slua.isValid(b) then
            b:SetBrushColor(color)
            b:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            local slot = parent:AddChildToCanvas(b)
            if slot then
                slot:SetAutoSize(false)
                slot:SetPosition(FVector2D(x, y))
                slot:SetSize(FVector2D(w, h))
                slot:SetZOrder(z or 0)
            end
        end
    end)
    table.insert(allWidgets, b)
    return b
end

local function FloatLayer(parent, x, y, w, h, color, z)
    local b = nil
    pcall(function()
        b = CGame:NewObjectFromPath("/Script/UMG.Border", parent)
        if b and slua.isValid(b) then
            b:SetBrushColor(color)
            b:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            local slot = parent:AddChildToCanvas(b)
            if slot then
                slot:SetAutoSize(false)
                slot:SetPosition(FVector2D(x, y))
                slot:SetSize(FVector2D(w, h))
                slot:SetZOrder(z or 0)
            end
        end
    end)
    return b
end

local function Text(parent, txt, x, y, size, color, z, alignX, alignY, bold)
    local t = nil
    pcall(function()
        t = CGame:NewObjectFromPath("/Script/UMG.TextBlock", parent)
        if t and slua.isValid(t) then
            t:SetText(txt)
            if FSlateColor then t:SetColorAndOpacity(FSlateColor(color))
            else t:SetColorAndOpacity(color) end
            if t.Font then local f = t.Font f.Size = size t.Font = f end
            if bold then
                pcall(function()
                    if t.Font then local f = t.Font f.TypefaceFontName = "Bold" t.Font = f end
                end)
            end
            t:SetRenderTransformPivot(FVector2D(alignX or 0.5, alignY or 0.5))
            t:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            local slot = parent:AddChildToCanvas(t)
            if slot then
                slot:SetAutoSize(true)
                slot:SetAlignment(FVector2D(alignX or 0.5, alignY or 0.5))
                slot:SetPosition(FVector2D(x, y))
                slot:SetZOrder(z or 100)
            end
        end
    end)
    table.insert(allWidgets, t)
    return t
end

-- ===== STYLISH NEON TEXT (premium glowing typography) =====
-- draws a soft crimson halo + drop shadow behind the main text
-- italic lean exactly like the reference photo (shear, tilt fallback)
local function StyleItalic(t)
    if not t or not slua.isValid(t) then return end
    local ok = pcall(function() t:SetRenderShear(10) end)
    if not ok then pcall(function() t:SetRenderTransformAngle(7) end) end
end

-- draws a soft crimson halo + drop shadow behind the main text
local function NeonText(parent, txt, x, y, size, color, z, alignX, alignY, italic)
    local d = 1 + math.floor(size / 30)
    local g = C.accent_neon
    local glowPos = { { x + d, y }, { x - d, y }, { x, y + d }, { x, y - d },
                      { x + 2, y + 2 } }
    for i = 1, 5 do
        local col = g
        if i == 5 then col = FLinearColor(0, 0, 0, 0.7) end
        local t = Text(parent, txt, glowPos[i][1], glowPos[i][2], size, col,
                       z - 1, alignX, alignY)
        if italic then StyleItalic(t) end
    end
    local main = Text(parent, txt, x, y, size, color, z, alignX, alignY)
    if italic then StyleItalic(main) end
    return main
end

-- Rotated glass reflection streak
local function GlassStreak(parent, x, y, w, h, color, z, angle)
    local b = nil
    pcall(function()
        b = CGame:NewObjectFromPath("/Script/UMG.Border", parent)
        if b and slua.isValid(b) then
            b:SetBrushColor(color)
            b:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            b:SetRenderTransformPivot(FVector2D(0.5, 0.5))
            b:SetRenderAngle(angle or -10)
            local slot = parent:AddChildToCanvas(b)
            if slot then
                slot:SetAutoSize(false)
                slot:SetPosition(FVector2D(x, y))
                slot:SetSize(FVector2D(w, h))
                slot:SetZOrder(z or 400)
            end
        end
    end)
    table.insert(allWidgets, b)
    return b
end

-- Hex color helper ("RRGGBB" -> FLinearColor)
local function HexColor(h)
    return FLinearColor(tonumber(h:sub(1, 2), 16) / 255,
                       tonumber(h:sub(3, 4), 16) / 255,
                       tonumber(h:sub(5, 6), 16) / 255, 1)
end

local function ShowMenu()
    if bgPanel and IsValid(bgPanel) then
        pcall(function() bgPanel:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
    end
end

local function HideMenu()
    if bgPanel and IsValid(bgPanel) then
        pcall(function() bgPanel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end
end

-- ===== GLASS CHECKBOX ROW UPDATE =====
local function UpdateToggleRow(rowData)
    if not rowData then return end
    local state = _G.VIPConfig[rowData.key]

    if rowData.boxFill and IsValid(rowData.boxFill) then
        pcall(function()
            rowData.boxFill:SetBrushColor(state and C.accent or C.bg_white)
        end)
    end

    if rowData.boxBorder and IsValid(rowData.boxBorder) then
        pcall(function()
            rowData.boxBorder:SetBrushColor(state and C.box_border_on or C.box_border)
        end)
    end

    if rowData.check and IsValid(rowData.check) then
        pcall(function()
            if state then
                rowData.check:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            else
                rowData.check:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
            end
        end)
    end

    -- Label: white ON / grey OFF (live update)
    if rowData.label and IsValid(rowData.label) then
        pcall(function()
            if FSlateColor then rowData.label:SetColorAndOpacity(FSlateColor(state and C.white or C.text_grey))
            else rowData.label:SetColorAndOpacity(state and C.white or C.text_grey) end
        end)
    end
end

-- ===== GLASS CHECKBOX ROW (checkbox + label, ON/OFF) =====
local function MakeToggleRow(parent, label, x, y, w, h, toggleKey)
    local state = _G.VIPConfig[toggleKey]
    local rowData = { key = toggleKey }

    local boxSize = math.min(22, h - 10)
    local boxX = x + 6
    local boxY = y + (h - boxSize) * 0.5

    -- glow halo when ON (premium)
    if state then
        Layer(parent, boxX - 4, boxY - 4, boxSize + 8, boxSize + 8, C.accent_glow, 299)
    end
    rowData.boxBorder = Layer(parent, boxX - 1, boxY - 1, boxSize + 2, boxSize + 2,
        state and C.box_border_on or C.box_border, 300)

    rowData.boxFill = Layer(parent, boxX, boxY, boxSize, boxSize,
        state and C.accent or C.bg_white, 301)

    rowData.check = Text(parent, "\u{2713}", boxX + boxSize * 0.5, boxY + boxSize * 0.5 - 1, 15, C.white, 305, 0.5, 0.5)
    if not state then
        pcall(function() rowData.check:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end

    rowData.label = Text(parent, label, boxX + boxSize + 12, y + h * 0.5, 15,
        state and C.white or C.text_grey, 300, 0, 0.5, true)

    rowData.btn = MakeBtn(parent, x, y, w, h, 900, function()
        _G.VIPConfig[toggleKey] = not _G.VIPConfig[toggleKey]
        UpdateToggleRow(rowData)
    end)

    table.insert(toggleRows, rowData)
    return rowData
end

-- ===== MENU CHILDREN BUILDER (uses panel's ACTUAL rendered size) =====
local function BuildChildren()
    if childrenBuilt then return end
    if not bgPanel or not slua.isValid(bgPanel) then return end

    -- Read the panel's real rendered size (it was sized by anchors = 60% x 65% of screen)
    local M_W, M_H = 972, 468
    pcall(function()
        local geo = bgPanel:GetCachedGeometry()
        local sz = geo:GetLocalSize()
        if sz and sz.X and sz.X > 300 and sz.Y > 200 then M_W = sz.X; M_H = sz.Y end
    end)
    M_W = math.floor(M_W); M_H = math.floor(M_H)

    local SW = math.floor(M_W * 0.20)          -- sidebar width (20%)
    local CW = M_W - SW                        -- content width
    local TOPTAB_H = 42

    -- ===== SOFT DROP SHADOW =====
    Layer(bgPanel, -10, -10, M_W + 20, M_H + 20, C.shadow3, -5)
    Layer(bgPanel, -6, -6, M_W + 12, M_H + 12, C.shadow2, -4)
    Layer(bgPanel, -3, -3, M_W + 6, M_H + 6, C.shadow1, -3)

    -- ===== FULL PREMIUM FRAME (double neon halo + crimson borders + glossy edge) =====
    -- outer neon halo: two glow rings for deep premium depth
    Layer(bgPanel, -9, -9, M_W + 18, M_H + 18, C.accent_glow, -2)
    Layer(bgPanel, -5, -5, M_W + 10, M_H + 10, C.accent_glow, -1)
    -- crisp double crimson border
    Layer(bgPanel, -2, -2, M_W + 4, M_H + 4, C.border_blue, 0)
    Layer(bgPanel, -1, -1, M_W + 2, M_H + 2, C.border_glass, 0)
    -- base + subtle 3-band vertical gradient (light -> main -> dark)
    Layer(bgPanel, 0, 0, M_W, M_H, C.bg_glass, 1)
    Layer(bgPanel, 0, 0, M_W, M_H * 0.38, C.bg_glass_hi, 1)
    Layer(bgPanel, 0, M_H * 0.72, M_W, M_H * 0.28, C.bg_glass3, 1)
    -- glossy metallic top edge (premium glass highlight)
    Layer(bgPanel, 0, 0, M_W, 1, FLinearColor(1.00, 0.55, 0.57, 0.30), 2)
    -- depth: top light edge + bottom inner shadow
    Layer(bgPanel, 0, 1, M_W, 2, C.border_glass, 2)
    Layer(bgPanel, 0, M_H - 4, M_W, 4, FLinearColor(0.0, 0.0, 0.0, 0.60), 2)
    Layer(bgPanel, 0, M_H - 3, M_W, 3, FLinearColor(0.0, 0.0, 0.0, 0.55), 2)
    -- premium esports corner brackets (L-shaped, bright crimson)
    local cbS = 18
    Layer(bgPanel, 0, 0, cbS, 3, C.accent_bright, 15)
    Layer(bgPanel, 0, 0, 3, cbS, C.accent_bright, 15)
    Layer(bgPanel, M_W - cbS, 0, cbS, 3, C.accent_bright, 15)
    Layer(bgPanel, M_W - 3, 0, 3, cbS, C.accent_bright, 15)
    Layer(bgPanel, 0, M_H - 3, cbS, 3, C.accent_bright, 15)
    Layer(bgPanel, 0, M_H - cbS, 3, cbS, C.accent_bright, 15)
    Layer(bgPanel, M_W - cbS, M_H - 3, cbS, 3, C.accent_bright, 15)
    Layer(bgPanel, M_W - 3, M_H - cbS, 3, cbS, C.accent_bright, 15)
    -- [CLEAN BG] REMOVED: radial glow patches, white streak strip, diagonal
    -- GlassStreak bands, ambient corner glows - these caused all the dirty
    -- white/grey streaks, diagonal bands and smudges inside the panel.
    -- Background is now clean: solid dark + subtle vertical gradient only.

    -- ===== LEFT SIDEBAR (subtle gradient + double neon divider) =====
    Layer(bgPanel, 0, 0, SW, M_H, C.bg_glass2, 2)
    Layer(bgPanel, 0, 0, SW, M_H * 0.30, C.bg_glass3, 2)
    Layer(bgPanel, 0, 0, SW, 2, C.border_glass, 3)
    -- double divider: bright core line + two glow strips
    Layer(bgPanel, SW - 2, 0, 1, M_H, C.border_glass, 3)
    Layer(bgPanel, SW, 0, 1, M_H, C.accent_glow, 3)
    Layer(bgPanel, SW + 2, 0, 2, M_H, C.accent_glow, 3)

    -- Circular logo (black circle, white RB)
    local logoSize = math.min(56, SW - 24)
    local logoX = (SW - logoSize) * 0.5
    local logoY = 20
    Layer(bgPanel, logoX - 5, logoY - 5, logoSize + 10, logoSize + 10, C.accent_glow, 3)
    Layer(bgPanel, logoX - 1, logoY - 1, logoSize + 2, logoSize + 2, C.accent_deep, 4)
    Layer(bgPanel, logoX, logoY, logoSize, logoSize, C.bg_black, 5)
    NeonText(bgPanel, "ROCKY", logoX + logoSize * 0.5, logoY + logoSize * 0.5, 13, C.white, 10, 0.5, 0.5)

    -- ===== VERTICAL NAV (adaptive heights - can never overflow) =====
    local navNames = {"HOME", "ESP", "AIMBOT", "SKINS", "MEMORY"}
    local navIcons = {"\u{2302}", "\u{25C9}", "\u{271A}", "\u{25A6}", "\u{2699}"}
    local navWidgets = {}
    local navPanels = {}
    local navY0 = logoY + logoSize + 18
    local navAvail = M_H - navY0 - 10
    local navItemH = math.min(46, math.floor(navAvail / #navNames))
    local navPad = 10

    local function SwitchNav(navIndex)
        for i = 1, #navWidgets do
            local nw = navWidgets[i]
            if nw then
                if i == navIndex then
                    if nw.pill and IsValid(nw.pill) then nw.pill:SetBrushColor(FLinearColor(0.76, 0.012, 0.019, 0.90)) end
                    if nw.edge and IsValid(nw.edge) then nw.edge:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end
                    if nw.glow and IsValid(nw.glow) then nw.glow:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end
                    if nw.txt and IsValid(nw.txt) then
                        if FSlateColor then nw.txt:SetColorAndOpacity(FSlateColor(C.white))
                        else nw.txt:SetColorAndOpacity(C.white) end
                    end
                    if nw.ic and IsValid(nw.ic) then
                        if FSlateColor then nw.ic:SetColorAndOpacity(FSlateColor(C.white))
                        else nw.ic:SetColorAndOpacity(C.white) end
                    end
                else
                    if nw.pill and IsValid(nw.pill) then nw.pill:SetBrushColor(C.transparent) end
                    if nw.edge and IsValid(nw.edge) then nw.edge:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
                    if nw.glow and IsValid(nw.glow) then nw.glow:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
                    if nw.txt and IsValid(nw.txt) then
                        if FSlateColor then nw.txt:SetColorAndOpacity(FSlateColor(C.text_grey))
                        else nw.txt:SetColorAndOpacity(C.text_grey) end
                    end
                end
            end
        end
        for i = 1, #navPanels do
            if navPanels[i] and IsValid(navPanels[i]) then
                if i == navIndex then
                    navPanels[i]:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                else
                    navPanels[i]:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                end
            end
        end
    end

    for i, navName in ipairs(navNames) do
        local ny = navY0 + (i - 1) * navItemH
        local isActive = (navName == "HOME")
        -- full-width active block (mockup: highlight extends full sidebar width)
        local pill = Layer(bgPanel, 0, ny, SW, navItemH - 2,
            isActive and FLinearColor(0.76, 0.012, 0.019, 0.90) or C.transparent, 4)
        local edge = Layer(bgPanel, 0, ny, SW, navItemH - 2, C.transparent, 5)
        if not isActive then
            pcall(function() edge:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
        end
        local navIc = Text(bgPanel, navIcons[i], 26, ny + (navItemH - 2) * 0.5, 15,
            isActive and C.white or C.text_grey, 10, 0.5, 0.5)
        local navGlow = Text(bgPanel, navName, 46, ny + (navItemH - 2) * 0.5, 15,
            C.accent_neon, 9, 0, 0.5, true)
        if not isActive then
            pcall(function() navGlow:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
        end
        local navTxt = Text(bgPanel, navName, 46, ny + (navItemH - 2) * 0.5, 15,
            isActive and C.white or C.text_grey, 10, 0, 0.5, true)
        local navIdx = i
        MakeBtn(bgPanel, 0, ny, SW, navItemH - 2, 900, function()
            SwitchNav(navIdx)
        end)
        navWidgets[i] = { pill = pill, ic = navIc, txt = navTxt, edge = edge, glow = navGlow }
    end

    -- ===== SIDEBAR VERSION BADGE =====
    Text(bgPanel, "v4 PREMIUM", SW * 0.5, M_H - 18, 10, C.accent_bright, 10, 0.5, 0.5)
    Layer(bgPanel, SW * 0.5 - 28, M_H - 28, 56, 1, C.divider, 5)

    -- ===== CONTENT PAGES =====

    -- Top tab bar helper
    local function BuildTopTabs(panel, names)
        Layer(panel, 0, 0, CW, TOPTAB_H, C.bg_glass3, 1)
        Layer(panel, 0, TOPTAB_H - 1, CW, 1, C.divider, 2)
        local ttw = CW / #names
        local tws = {}
        for i, tname in ipairs(names) do
            local tx = (i - 1) * ttw
            local isActive = (i == 1)
            local underline = Layer(panel, tx + 8, TOPTAB_H - 3, ttw - 16, 3, C.accent, 4)
            local ulGlow = Layer(panel, tx + 4, TOPTAB_H - 5, ttw - 8, 7, C.accent_glow, 3)
            if not isActive then
                pcall(function() underline:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
                pcall(function() ulGlow:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
            end
            local ttxt = Text(panel, tname, tx + ttw * 0.5, TOPTAB_H * 0.5, 14,
                isActive and C.accent or C.text_grey, 10, 0.5, 0.5)
            local idx = i
            MakeBtn(panel, tx, 0, ttw, TOPTAB_H, 900, function()
                for j = 1, #tws do
                    local tw = tws[j]
                    if tw then
                        if j == idx then
                            if tw.ug and IsValid(tw.ug) then tw.ug:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end
                            if tw.u and IsValid(tw.u) then tw.u:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end
                            if tw.t and IsValid(tw.t) then
                                if FSlateColor then tw.t:SetColorAndOpacity(FSlateColor(C.accent))
                                else tw.t:SetColorAndOpacity(C.accent) end
                            end
                        else
                            if tw.ug and IsValid(tw.ug) then tw.ug:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
                            if tw.u and IsValid(tw.u) then tw.u:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end
                            if tw.t and IsValid(tw.t) then
                                if FSlateColor then tw.t:SetColorAndOpacity(FSlateColor(C.text_grey))
                                else tw.t:SetColorAndOpacity(C.text_grey) end
                            end
                        end
                    end
                end
            end)
            tws[i] = { u = underline, ug = ulGlow, t = ttxt }
        end
    end

    -- Two-column grid helper (adaptive row height - can never overflow)
    local function BuildOptionsPage(panel, subL, subR, options)
        local padX = 22
        local colGap = 16
        local colW = (CW - padX * 2 - colGap) * 0.5
        local subY = TOPTAB_H + 14
        local gridY = subY + 30

        Text(panel, subL, padX + 5, subY + 1, 14, FLinearColor(0.0, 0.0, 0.0, 0.6), 199, 0, 0.5)
        Text(panel, subL, padX + 4, subY, 14, C.accent, 200, 0, 0.5, true)
        Text(panel, subR, padX + colW + colGap + 5, subY + 1, 14, FLinearColor(0.0, 0.0, 0.0, 0.6), 199, 0, 0.5)
        Text(panel, subR, padX + colW + colGap + 4, subY, 14, C.accent, 200, 0, 0.5, true)
        Layer(panel, padX, subY + 12, colW - 10, 1, C.divider, 200)
        Layer(panel, padX + colW + colGap, subY + 12, colW - 10, 1, C.divider, 200)

        -- Adaptive row height: rows ALWAYS fit inside the panel
        local nRows = math.ceil(#options / 2)
        local availH = M_H - gridY - 8
        local rowH = math.min(44, math.floor(availH / nRows))
        if rowH < 26 then rowH = 26 end

        for i, opt in ipairs(options) do
            if _G.VIPConfig[opt.key] == nil then _G.VIPConfig[opt.key] = false end
            local col = ((i - 1) % 2)
            local row = math.floor((i - 1) / 2)
            local cx = padX + col * (colW + colGap)
            local cy = gridY + row * rowH
            MakeToggleRow(panel, opt.label, cx, cy, colW, rowH, opt.key)
        end
    end

    -- Content page panel helper
    local function MakeContentPanel(visible)
        local panel = nil
        pcall(function()
            panel = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", bgPanel)
            if panel and slua.isValid(panel) then
                local slot = bgPanel:AddChildToCanvas(panel)
                if slot then
                    slot:SetAutoSize(false)
                    slot:SetPosition(FVector2D(SW, 0))
                    slot:SetSize(FVector2D(CW, M_H))
                    slot:SetZOrder(10)
                end
                if visible then
                    panel:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                else
                    panel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                end
            end
        end)
        return panel
    end

    -- HOME page (photo banner + branding)
    local homePanel = MakeContentPanel(true)
    if homePanel and slua.isValid(homePanel) then
        local cx = CW * 0.5
        -- ===== PHOTO BANNER (greedy-mesh pixel art, 56x40) =====
        local PH_COLS, PH_ROWS = 150, 112
        local photoRects = _PHOTO_RECTS_ULTRA
        -- photo area: RIGHT side, ~40% menu width (mockup)
        local availH = M_H * 0.50
        local availW = CW * 0.40
        local cellS = math.floor(math.min(availH / PH_ROWS, availW / PH_COLS))
        if cellS < 2 then cellS = 2 end
        local phW = cellS * PH_COLS
        local phH = cellS * PH_ROWS
        local phX = CW - phW - 24
        local phY = math.floor((M_H - phH) * 0.5)
        -- glow halo + black backing under cells
        Layer(homePanel, phX - 13, phY - 13, phW + 26, phH + 26, C.accent_glow, 2)
        Layer(homePanel, phX - 8, phY - 8, phW + 16, phH + 16, C.accent_glow, 3)
        Layer(homePanel, phX - 4, phY - 4, phW + 8, phH + 8, C.bg_black, 4)
        -- HD rectangle cells: BATCHED creation (300/frame, no freeze)
        local totalRects = #photoRects
        local rectIdx = 1
        local function BuildPhotoChunk()
            if not homePanel or not slua.isValid(homePanel) then return end
            local n = 0
            while rectIdx <= totalRects and n < 400 do
                local rc = photoRects[rectIdx]
                local r1, r2, c1, c2, hx = rc[1], rc[2], rc[3], rc[4], rc[5]
                Layer(homePanel, phX + (c1 - 1) * cellS, phY + (r1 - 1) * cellS,
                    (c2 - c1 + 1) * cellS + 1, (r2 - r1 + 1) * cellS + 1, HexColor(hx), 7)
                rectIdx = rectIdx + 1
                n = n + 1
            end
            if rectIdx <= totalRects then
                pcall(function()
                    local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
                    if pc and IsValid(pc) and pc.AddGameTimer then
                        pc:AddGameTimer(0.05, false, function() pcall(BuildPhotoChunk) end)
                    else
                        pcall(BuildPhotoChunk)
                    end
                end)
            end
        end
        BuildPhotoChunk()
        -- blue accent frame OUTSIDE the photo area
        Layer(homePanel, phX - 4, phY - 4, phW + 8, 2, C.accent, 8)
        Layer(homePanel, phX - 4, phY + phH + 2, phW + 8, 2, C.accent, 8)
        Layer(homePanel, phX - 4, phY - 4, 2, phH + 8, C.accent, 8)
        Layer(homePanel, phX + phW + 2, phY - 4, 2, phH + 8, C.accent, 8)

        -- ===== TEXT BELOW PHOTO (clean, no card/lines) =====
        local newPhY = math.min(phY + phH + 30, M_H - 50)
        local newCenter = phX + phW * 0.5

        -- crown mark above ROCKY (centered, with shadow + glow)
        Text(homePanel, "\u{265B}", newCenter + 1, newPhY + 1, 20, FLinearColor(0.0, 0.0, 0.0, 0.6), 8, 0.5, 0.5)
        Text(homePanel, "\u{265B}", newCenter, newPhY, 20, C.accent_bright, 9, 0.5, 0.5)

        -- "ROCKY BHAI" (bold title, white neon italic, size 25)
        local rockyY = newPhY + 22
        Text(homePanel, "ROCKY BHAI", newCenter + 2, rockyY + 2, 25, FLinearColor(0.0, 0.0, 0.0, 0.7), 8, 0.5, 0.5)
        NeonText(homePanel, "ROCKY BHAI", newCenter, rockyY, 25, C.white, 9, 0.5, 0.5, true)

        -- [REMOVED] CEO INDIA + Nepotism line

        -- ===== LEFT SIDE TEXT (mockup exact: NO card, directly on bg, LEFT-aligned) =====
        local tX = 46
        local y1 = math.floor(M_H * 0.17)
        -- PREMIUM LUA heading (reference exact style: crown + two-tone italic + neon)
        local hSize = 44
        -- red crown icon at the left of the heading
        Text(homePanel, "\u{265B}", tX + 1, y1 + 1, 30, C.accent_neon, 9, 0.5, 0.5)
        Text(homePanel, "\u{265B}", tX, y1, 30, C.accent_bright, 10, 0.5, 0.5)
        local hx = tX + 38
        -- PREMIUM in white (italic, neon)
        local tPrem = NeonText(homePanel, "PREMIUM", hx, y1, hSize, C.white, 10, 0, 0.5, true)
        -- LUA in bright crimson, placed right after PREMIUM's real width
        local premW = 210
        pcall(function()
            local sz = tPrem:GetDesiredSize()
            if sz and sz.X and sz.X > 20 then premW = sz.X end
        end)
        NeonText(homePanel, "LUA", hx + premW + 16, y1, hSize, C.accent_bright, 10, 0, 0.5, true)
        -- premium double separator: soft glow bar + bright core line
        Layer(homePanel, tX + 1, y1 + 38, 182, 6, C.accent_glow, 4)
        Layer(homePanel, tX + 2, y1 + 40, 180, 2, C.accent_bright, 5)
        -- Subtitle (off-white, with premium drop shadow)
        Text(homePanel, "Well Come Tu Premium File", tX + 3, y1 + 73, 20, FLinearColor(0, 0, 0, 0.65), 9, 0, 0.5)
        Text(homePanel, "Well Come Tu Premium File", tX + 2, y1 + 72, 20, FLinearColor(0.80, 0.80, 0.82, 1.0), 10, 0, 0.5)
        -- User + ROCKY BHAI (BOLD + shadow)
        local y2 = y1 + 116
        Text(homePanel, "\u{263A}", tX + 4, y2 + 1, 20, FLinearColor(0.0, 0.0, 0.0, 0.6), 9, 0.5, 0.5)
        Text(homePanel, "\u{263A}", tX + 4, y2, 20, C.accent_bright, 10, 0.5, 0.5)
        Text(homePanel, "ROCKY BHAI", tX + 30, y2 + 2, 26, FLinearColor(0.0, 0.0, 0.0, 0.7), 9, 0, 0.5)
        NeonText(homePanel, "ROCKY BHAI", tX + 28, y2, 26, C.white, 10, 0, 0.5, true)
        -- Telegram button (bottom-left of text block)
        local y3 = y2 + 44
        local btnW = 236
        local btnH = 48
        local btnX = tX + 4
        -- soft outer glow (double halo for premium depth)
        Layer(homePanel, btnX - 9, y3 - 9, btnW + 18, btnH + 18, C.accent_glow, 2)
        Layer(homePanel, btnX - 4, y3 - 4, btnW + 8, btnH + 8, C.accent_glow, 3)
        -- elegant thin outline
        Layer(homePanel, btnX - 1, y3 - 1, btnW + 2, btnH + 2, C.accent, 4)
        -- deep navy fill with gradient
        Layer(homePanel, btnX, y3, btnW, btnH * 0.5, FLinearColor(0.012, 0.005, 0.007, 0.98), 5)
        Layer(homePanel, btnX, y3 + btnH * 0.5, btnW, btnH * 0.5, C.bg_black, 5)
        -- inner glow accents
        Layer(homePanel, btnX, y3, btnW, 1, C.accent_bright, 6)
        Layer(homePanel, btnX + 1, y3 + btnH - 2, btnW - 2, 1, C.accent_deep, 6)
        Text(homePanel, "\u{2708}", btnX + 30, y3 + btnH * 0.5, 17, C.accent_bright, 10, 0.5, 0.5)
        Text(homePanel, "Dm @ROCKYBHAI711", btnX + 133, y3 + btnH * 0.5 + 1, 15, FLinearColor(0, 0, 0, 0.6), 9, 0.5, 0.5)
        Text(homePanel, "Dm @ROCKYBHAI711", btnX + 132, y3 + btnH * 0.5, 15, C.white, 10, 0.5, 0.5, true)
        MakeBtn(homePanel, btnX, y3, btnW, btnH, 900, function() end)
        -- [REMOVED] BOSS branding near bottom
    end

    -- ESP page (photo exact)
    local espPanel = MakeContentPanel(false)
    if espPanel and slua.isValid(espPanel) then
        BuildTopTabs(espPanel, {"Player & Bot", "Style & Mode", "Colors"})
        BuildOptionsPage(espPanel, "Player ESP", "Bot & Info ESP", {
            {label = "Enable ESP",  key = "ESP_Enabled"},
            {label = "Box",          key = "ESP_Box"},
            {label = "Health",       key = "ESP_HealthBar"},
            {label = "Distance",     key = "ESP_Distance"},
            {label = "Behind",       key = "ESP_Enemy"},
            {label = "Line",         key = "ESP_Line"},
            {label = "In-Hand",      key = "ESP_WeaponIcon"},
            {label = "Skeleton",     key = "ESP_Skeleton"},
            {label = "Radar",        key = "ESP_Radar"},
            {label = "Name",         key = "ESP_Name"},
            {label = "Ignore Bot",   key = "ESP_Team"},
            {label = "Show All Names", key = "ESP_TotalCount"},
            {label = "Enemy Counter", key = "ESP_Vehicle"},
            {label = "Landing",      key = "ESP_Airdrop"},
            {label = "Grenade Warning", key = "ESP_Item"},
        })
    end

    -- AIMBOT page
    local aimPanel = MakeContentPanel(false)
    if aimPanel and slua.isValid(aimPanel) then
        BuildTopTabs(aimPanel, {"Basic Aim", "Advanced", "Filter"})
        BuildOptionsPage(aimPanel, "Aimbot", "Aim Info", {
            {label = "Aim Enable",   key = "AIM_Enabled"},
            {label = "Aim Fov",      key = "AIM_FOV"},
            {label = "Aim Bot",      key = "AIM_Bot"},
            {label = "Aim Smooth",   key = "AIM_Smooth"},
            {label = "Aim Silent",   key = "AIM_Silent"},
            {label = "Aim Visible",  key = "AIM_Visible"},
            {label = "Aim Distance", key = "AIM_Distance"},
            {label = "Aim Bone",     key = "AIM_Bone"},
        })
    end

    -- SKINS page
    local skinPanel = MakeContentPanel(false)
    if skinPanel and slua.isValid(skinPanel) then
        BuildTopTabs(skinPanel, {"Rifles", "Snipers", "SMGs"})
        BuildOptionsPage(skinPanel, "Weapon Skins", "More Skins", {
            {label = "M416 Skin",    key = "SKIN_M416"},
            {label = "KAR98 Skin",   key = "SKIN_KAR98"},
            {label = "AKM Skin",     key = "SKIN_AKM"},
            {label = "UMP45 Skin",   key = "SKIN_UMP45"},
            {label = "AWM Skin",     key = "SKIN_AWM"},
            {label = "SCARL Skin",   key = "SKIN_SCARL"},
            {label = "DP28 Skin",    key = "SKIN_DP28"},
            {label = "GROZA Skin",   key = "SKIN_GROZA"},
        })
    end

    -- MEMORY page
    local memPanel = MakeContentPanel(false)
    if memPanel and slua.isValid(memPanel) then
        BuildTopTabs(memPanel, {"Hacks", "Visual", "Misc"})
        BuildOptionsPage(memPanel, "Memory Hacks", "Environment", {
            {label = "Antiban",      key = "MEM_AntiBan"},
            {label = "No Recoil",    key = "MEM_NoRecoil"},
            {label = "Wallhack",     key = "MEM_Wallhack"},
            {label = "No Shake",     key = "MEM_NoShake"},
            {label = "Speed Hack",   key = "MEM_Speed"},
            {label = "No Fog",       key = "MEM_NoFog"},
            {label = "Black Sky",    key = "MEM_BlackSky"},
            {label = "No Grass",     key = "MEM_NoGrass"},
        })
    end

    -- nav panels mapping (nav order: HOME, ESP, AIMBOT, SKINS, MEMORY)
    navPanels[1] = homePanel
    navPanels[2] = espPanel
    navPanels[3] = aimPanel
    navPanels[4] = skinPanel
    navPanels[5] = memPanel

    childrenBuilt = true
end

-- ===== BUILD MENU (panel via anchors = exact 60% x 65% of screen, centered) =====
local function BuildMenu()
    if menuBuilt and bgPanel and IsValid(bgPanel) then
        ShowMenu()
        return
    end

    local canvas = GetCanvas()
    if not canvas then return end

    pcall(function()
        bgPanel = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", canvas)
        if bgPanel and slua.isValid(bgPanel) then
            local slot = canvas:AddChildToCanvas(bgPanel)
            if slot then
                slot:SetAutoSize(false)
                slot:SetZOrder(10000)
                -- EXACT 60% width x 65% height, centered (anchor-based, resolution independent)
                slot:SetAnchors(FAnchors(0.125, 0.20, 0.875, 0.80))
                slot:SetAlignment(FVector2D(0, 0))
                slot:SetPosition(FVector2D(0, 0))
                slot:SetSize(FVector2D(0, 0))
            end
        end
    end)
    if not bgPanel or not slua.isValid(bgPanel) then return end

    -- Build children from the panel's REAL rendered size after layout (1 frame later)
    pcall(function()
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if pc and IsValid(pc) and pc.AddGameTimer then
            pc:AddGameTimer(0.25, false, function() pcall(BuildChildren) end)
        else
            BuildChildren()
        end
    end)

    menuBuilt = true
    isMenuOpen = true
    ShowMenu()
end

-- ===== GLASS FLOAT BUTTON =====
local function CreateFloat()
    if floatItem and floatItem.btn and IsValid(floatItem.btn) then return end
    floatItem = nil
    pcall(function()
        local canvas = GetCanvas()
        if not canvas then return end

        floatItem = {}
        local fX = 20
        local fY = 15
        local fW = 120
        local fH = 50

        floatItem.s0 = FloatLayer(canvas, fX - 6, fY - 6, fW + 12, fH + 12, C.shadow2, 11896)
        floatItem.s1 = FloatLayer(canvas, fX - 3, fY - 3, fW + 6, fH + 6, C.shadow1, 11898)
        floatItem.s5 = FloatLayer(canvas, fX - 1, fY - 1, fW + 2, fH + 2, C.accent, 11901)
        floatItem.s8 = FloatLayer(canvas, fX, fY, fW, fH, FLinearColor(0.0, 0.0, 0.0, 1.0), 11902)
        floatItem.s9 = FloatLayer(canvas, fX, fY, fW, fH * 0.5, FLinearColor(0.02, 0.008, 0.009, 1.0), 11903)
        floatItem.s13 = FloatLayer(canvas, fX + 2, fY + 1, fW - 4, 1, C.accent, 11905)
        floatItem.s14 = FloatLayer(canvas, fX + 2, fY + fH - 2, fW - 4, 1, C.accent, 11905)
        floatItem.s16 = FloatLayer(canvas, fX + 2, fY + 4, fW - 4, fH - 8, FLinearColor(0.0, 0.0, 0.0, 0.92), 11906)

        pcall(function()
            floatItem.text = CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas)
            if floatItem.text and slua.isValid(floatItem.text) then
                floatItem.text:SetText("ROCKY")
                if FSlateColor then floatItem.text:SetColorAndOpacity(FSlateColor(C.accent))
                else floatItem.text:SetColorAndOpacity(C.accent) end
                if floatItem.text.Font then local f = floatItem.text.Font f.Size = 17 floatItem.text.Font = f end
                floatItem.text:SetRenderScale(FVector2D(1.15, 1.15))
                floatItem.text:SetRenderTransformPivot(FVector2D(0.5, 0.5))
                floatItem.text:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                local slot = canvas:AddChildToCanvas(floatItem.text)
                if slot then
                    slot:SetAutoSize(true)
                    slot:SetAlignment(FVector2D(0.5, 0.5))
                    slot:SetPosition(FVector2D(fX + fW * 0.5, fY + fH * 0.5))
                    slot:SetZOrder(12001)
                end
            end
        end)

        floatItem.s17 = FloatLayer(canvas, fX + fW - 10, fY + 4, 5, 5, C.accent, 12000)

        pcall(function()
            floatItem.btn = CGame:NewObjectFromPath("/Script/UMG.Button", canvas)
            if floatItem.btn and slua.isValid(floatItem.btn) then
                pcall(function() floatItem.btn:SetColorAndOpacity(C.transparent) end)
                pcall(function() floatItem.btn:SetBackgroundColor(C.transparent) end)
                pcall(function() floatItem.btn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end)
                local slot = canvas:AddChildToCanvas(floatItem.btn)
                if slot then
                    slot:SetAutoSize(false)
                    slot:SetPosition(FVector2D(fX, fY))
                    slot:SetSize(FVector2D(fW, fH))
                    slot:SetZOrder(12002)
                end
                pcall(function()
                    if floatItem.btn.OnClicked then
                        floatItem.btn.OnClicked:Add(function()
                            pcall(function()
                                isMenuOpen = not isMenuOpen
                                if isMenuOpen then
                                    if menuBuilt and bgPanel and IsValid(bgPanel) then
                                        ShowMenu()
                                    else
                                        BuildMenu()
                                    end
                                else
                                    HideMenu()
                                end
                            end)
                        end)
                    end
                end)
            end
        end)
    end)
end

-- ===== INIT =====
pcall(function()
    local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
    if pc and IsValid(pc) then
        CreateFloat()
        pc:AddGameTimer(3, true, function()
            if not floatItem or not floatItem.btn or not IsValid(floatItem.btn) then
                floatItem = nil
                CreateFloat()
            end
        end)
    end
end)
